import { spawn } from 'node:child_process';
import { chromium } from '@playwright/test';

const port = 4300;
const server = spawn('node', ['server.mjs', '--port', String(port)], { stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 500));

try {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: 'load' });
  await page.waitForTimeout(500);

  // Check initial state
  const initialNotes = await page.$$('#feed article.note');
  console.log(`✓ Initial notes loaded: ${initialNotes.length} notes`);

  // Test search
  await page.fill('#search', 'Douro');
  await page.waitForTimeout(300);
  const searchResults = await page.$$('#feed article.note');
  const resultsLine = await page.textContent('#results-line');
  console.log(`✓ Search working: ${searchResults.length} results, "${resultsLine}"`);

  // Clear search
  await page.fill('#search', '');
  await page.waitForTimeout(300);
  const allNotes = await page.$$('#feed article.note');
  console.log(`✓ Search cleared: ${allNotes.length} notes`);

  // Test adding a note
  await page.fill('#title', 'Test Note');
  await page.fill('#body', 'This is a <b>test</b> note with <i>formatting</i>.');
  await page.fill('#avatar', 'data:image/svg+xml;utf8,%3Csvg%3E%3C/svg%3E');
  await page.click('#note-form button');
  await page.waitForTimeout(300);

  const afterAddNotes = await page.$$('#feed article.note');
  console.log(`✓ Note added: ${afterAddNotes.length} notes (was ${initialNotes.length})`);

  // Check if first note is the new one (newest-first)
  const firstNoteTitle = await page.textContent('#feed article.note .note-title');
  console.log(`✓ Newest-first ordering: first note is "${firstNoteTitle}"`);

  // Test deep link - click a note
  const noteToSelect = await page.$('#feed article.note[data-note-id="1"]');
  if (noteToSelect) {
    await noteToSelect.click();
    await page.waitForTimeout(300);
    const url = page.url();
    console.log(`✓ Deep link: ${url}`);
  }

  // Check rich text rendering
  const bodyHtml = await page.innerHTML('#feed article.note .note-body');
  if (bodyHtml.includes('<b>') || bodyHtml.includes('<strong>')) {
    console.log(`✓ Rich text rendering: tags are preserved`);
  }

  await browser.close();
  console.log('\n✓ All tests passed!');
} finally {
  server.kill();
}
EOF
